-- Auditoria PF 2025 Delegado de Polícia Federal — lote 2 (11 itens de
-- Direito Civil, Processual Civil e Empresarial).

update public.official_exam_questions
set review_note=$q$Errado. A configuração do nexo de causalidade não exige necessariamente uma conduta comissiva ou omissiva imputável ao agente: nos regimes de responsabilidade civil OBJETIVA (baseados em risco, guarda ou atividade — ex.: dono de animal, empregador por ato de empregado, fornecedor por fato do produto), o nexo causal liga o dano ao FATO GERADOR, independentemente de culpa ou mesmo de uma "conduta" no sentido estrito do agente responsável.
Fonte oficial: arts. 186, 187 e 927, parágrafo único, CC/2002 (planalto.gov.br) — responsabilidade civil objetiva e teoria do risco.$q$,
    legal_audit_completed=true, current_syllabus_topic_id=syllabus_topic_id, law_version_checked_at=now(),
    legal_basis='[{"fonte":"arts. 186, 187, 927 CC/2002","url":"https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm"}]'::jsonb
where exam_year=2025 and career_name='Delegado de Polícia Federal' and item_number=36;

update public.official_exam_questions
set review_note=$q$Errado. O registro imobiliário tem natureza predominantemente constitutiva para a transferência da propriedade entre as partes (art. 1.245, CC), mas a oponibilidade a terceiros de certos direitos (como a posse ou a cessão de direitos possessórios, e mesmo a eficácia de certos negócios entre as partes) pode decorrer de outros fatos jurídicos antes do registro — a afirmação de que "somente com o registro" se cria qualquer direito oponível a terceiros é excessivamente categórica e não reflete o sistema registral brasileiro em sua complexidade (ex.: posse é oponível a terceiros independentemente de registro).
Fonte oficial: art. 1.245, CC/2002; arts. 1.196 e seguintes, CC/2002 (posse), planalto.gov.br.$q$,
    legal_audit_completed=true, current_syllabus_topic_id=syllabus_topic_id, law_version_checked_at=now(),
    legal_basis='[{"fonte":"art. 1.245 e arts. 1.196 e ss., CC/2002","url":"https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm"}]'::jsonb
where exam_year=2025 and career_name='Delegado de Polícia Federal' and item_number=37;

update public.official_exam_questions
set review_note=$q$Errado. A apreensão física de um bem móvel por meio de furto ou roubo NÃO impede a caracterização da posse (ainda que injusta, por ser violenta ou clandestina) — o possuidor de má-fé/injusto ainda exerce poder de fato sobre a coisa, o que caracteriza posse, apenas com efeitos jurídicos distintos (ex.: impossibilidade de usucapião ordinária, sujeição a interditos possessórios por quem tem melhor posse).
Fonte oficial: arts. 1.196, 1.200 e 1.208, CC/2002 (planalto.gov.br).$q$,
    legal_audit_completed=true, current_syllabus_topic_id=syllabus_topic_id, law_version_checked_at=now(),
    legal_basis='[{"fonte":"arts. 1.196, 1.200, 1.208, CC/2002","url":"https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm"}]'::jsonb
where exam_year=2025 and career_name='Delegado de Polícia Federal' and item_number=38;

update public.official_exam_questions
set review_note=$q$Errado. Reconhecida a continência, a ação contida não é necessariamente extinta: o CPC determina a reunião dos processos para julgamento conjunto perante o juízo prevento (ou a extinção da ação contida sem resolução de mérito SOMENTE se já tiver sido proposta a ação continente antes), não a extinção automática independentemente da ordem de propositura.
Fonte oficial: art. 57, CPC/2015 (planalto.gov.br).$q$,
    legal_audit_completed=true, current_syllabus_topic_id=syllabus_topic_id, law_version_checked_at=now(),
    legal_basis='[{"fonte":"art. 57, CPC/2015","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm"}]'::jsonb
where exam_year=2025 and career_name='Delegado de Polícia Federal' and item_number=39;

update public.official_exam_questions
set review_note=$q$Errado. Na ação de homologação de decisão estrangeira, o STJ não examina o mérito da causa (sistema de delibação): o juízo de homologação é de natureza formal/processual, não lhe cabendo decretar a prescrição do direito material discutido no título estrangeiro, que é matéria de mérito já decidida pela jurisdição de origem.
Fonte oficial: art. 961 e seguintes, CPC/2015; jurisprudência do STJ sobre o sistema de delibação na homologação de sentença estrangeira.$q$,
    legal_audit_completed=true, current_syllabus_topic_id=syllabus_topic_id, law_version_checked_at=now(),
    legal_basis='[{"fonte":"art. 961 e ss., CPC/2015; jurisprudência STJ sobre delibação","url":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13105.htm"}]'::jsonb
where exam_year=2025 and career_name='Delegado de Polícia Federal' and item_number=40;

update public.official_exam_questions
set review_note=$q$Correto. O mandado de segurança individual destina-se à proteção de direito líquido e certo PRÓPRIO do impetrante — não serve para a tutela de interesses coletivos (hipótese do mandado de segurança coletivo) nem para defesa abstrata da ordem jurídica (que é função de ações de controle concentrado de constitucionalidade).
Fonte oficial: art. 5º, LXIX, CF/1988; art. 1º, Lei 12.016/2009 (planalto.gov.br).$q$,
    legal_audit_completed=true, current_syllabus_topic_id=syllabus_topic_id, law_version_checked_at=now(),
    legal_basis='[{"fonte":"art. 5º, LXIX, CF/1988; art. 1º, Lei 12.016/2009","url":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2009/lei/l12016.htm"}]'::jsonb
where exam_year=2025 and career_name='Delegado de Polícia Federal' and item_number=41;

update public.official_exam_questions
set review_note=$q$Correto. A jurisprudência do STF/STJ firmou-se no sentido de que a demonstração de prejuízo material (patrimonial) aos cofres públicos não é condição indispensável para o cabimento da ação popular, que também protege a moralidade administrativa e outros bens de natureza não patrimonial, cujo dano pode ser presumido conforme o ato impugnado.
Fonte oficial: art. 5º, LXXIII, CF/1988; jurisprudência consolidada sobre ação popular e lesividade presumida.$q$,
    legal_audit_completed=true, current_syllabus_topic_id=syllabus_topic_id, law_version_checked_at=now(),
    legal_basis='[{"fonte":"art. 5º, LXXIII, CF/1988; jurisprudência sobre ação popular","url":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm"}]'::jsonb
where exam_year=2025 and career_name='Delegado de Polícia Federal' and item_number=42;

update public.official_exam_questions
set review_note=$q$Errado. Para fins de apuração de haveres em sociedades simples, é SIM possível (e frequentemente necessário) levar em consideração elementos tipicamente associados a sociedades empresárias, como o fundo de comércio/clientela ou o acervo técnico acumulado, quando esses elementos efetivamente integram o patrimônio e agregam valor econômico à sociedade, independentemente de sua natureza simples ou empresária.
Fonte oficial: arts. 1.031 e 1.034, CC/2002 (apuração de haveres, planalto.gov.br).$q$,
    legal_audit_completed=true, current_syllabus_topic_id=syllabus_topic_id, law_version_checked_at=now(),
    legal_basis='[{"fonte":"arts. 1.031, 1.034, CC/2002","url":"https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm"}]'::jsonb
where exam_year=2025 and career_name='Delegado de Polícia Federal' and item_number=43;

update public.official_exam_questions
set review_note=$q$Errado. A sociedade de propósito específico (SPE) NÃO é um novo tipo societário criado pelo Código Civil de 2002 — o CC não disciplina nem distingue a SPE como tipo próprio; trata-se apenas de uma sociedade constituída sob um dos tipos JÁ EXISTENTES (como Ltda. ou S.A.) com objeto social restrito a um propósito específico, figura que ganhou relevância sobretudo a partir da Lei 11.079/2004 (parcerias público-privadas).
Fonte oficial: Lei 11.079/2004; doutrina consolidada de Direito Empresarial sobre SPE.$q$,
    legal_audit_completed=true, current_syllabus_topic_id=syllabus_topic_id, law_version_checked_at=now(),
    legal_basis='[{"fonte":"Lei 11.079/2004 - Parcerias Público-Privadas (origem da figura da SPE)","url":"https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2004/lei/l11079.htm"}]'::jsonb
where exam_year=2025 and career_name='Delegado de Polícia Federal' and item_number=44;

update public.official_exam_questions
set review_note=$q$Correto. A Lei 11.101/2005 (Recuperação Judicial e Falência) não se aplica, entre outros, a cooperativas de crédito, consórcios, entidades de previdência complementar e sociedades operadoras de plano de assistência à saúde — exceto, nesta última hipótese, quando se tratar de cooperativa médica, que se submete ao regime falimentar comum.
Fonte oficial: art. 2º, Lei 11.101/2005 (planalto.gov.br).$q$,
    legal_audit_completed=true, current_syllabus_topic_id=syllabus_topic_id, law_version_checked_at=now(),
    legal_basis='[{"fonte":"art. 2º, Lei 11.101/2005","url":"https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2005/lei/l11101.htm"}]'::jsonb
where exam_year=2025 and career_name='Delegado de Polícia Federal' and item_number=45;

update public.official_exam_questions
set review_note=$q$Errado. A Constituição não exclui de forma absoluta a possibilidade de expulsão de estrangeiro que tenha prole brasileira sob sua guarda e dependência: a jurisprudência do STF/STJ (inclusive a Súmula 1 do STJ, hoje mitigada) admite exceções a essa proteção conforme a gravidade da conduta do estrangeiro (ex.: tráfico de drogas, crimes graves), não havendo uma vedação constitucional absoluta e automática à expulsão nesses casos.
Fonte oficial: jurisprudência do STF/STJ sobre expulsão de estrangeiro com filho brasileiro e ponderação de interesses.$q$,
    legal_audit_completed=true, current_syllabus_topic_id=syllabus_topic_id, law_version_checked_at=now(),
    legal_basis='[{"fonte":"jurisprudência STF/STJ sobre expulsão de estrangeiro com prole brasileira"}]'::jsonb
where exam_year=2025 and career_name='Delegado de Polícia Federal' and item_number=46;
